'use strict';
window.ActivityQr=(()=>{
 const configs={};let request=0;
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const loopback=host=>/^(localhost|.*\.localhost|127\.[\d.]+|0\.0\.0\.0|\[::1\]|::1)$/i.test(host);
 const privateIp=host=>/^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(host);
 function targetUrl(base,file,grade,target){const url=new URL(base);if(!['http:','https:'].includes(url.protocol)||loopback(url.hostname)||url.username||url.password)throw Error('localhost·파일 주소 대신 학생 기기에서 접속할 공개 주소나 교실 IP 주소를 입력해 주세요.');const result=new URL(file,new URL('.',url.href.endsWith('/')?url.href:url.href));result.hash=`student/${grade}/${target}`;return result.href}
 function build(topic){const config=configs[topic],input=document.getElementById('activity-share-base'),result=document.getElementById('activity-qr-result'),status=document.getElementById('activity-qr-status');if(!input||!result)return;
  try{const href=targetUrl(input.value.trim(),config.file,config.grade(),document.getElementById('activity-qr-target').value);const q=window.qrcode(0,'M');q.addData(href);q.make();result.innerHTML=q.createSvgTag({cellSize:5,margin:4,scalable:true})+`<a href="${esc(href)}" target="_blank" rel="noopener">학생 활동 직접 열기 ↗</a><p class="qr-url">${esc(href)}</p>`;status.textContent=privateIp(new URL(href).hostname)?'같은 교실 와이파이에서 학생 기기 한 대로 먼저 접속해 보세요.':'인터넷에 연결된 학생 기기에서 먼저 접속해 보세요.';try{localStorage.setItem(`holiday-share:${topic}`,input.value.trim())}catch{}}
  catch(error){result.innerHTML='<p>접속 가능한 주소를 입력하면 QR이 표시됩니다.</p>';status.textContent=error.message==='Invalid URL'?'http:// 또는 https://로 시작하는 주소를 입력해 주세요.':error.message}
 }
 async function open(topic){const config=configs[topic],token=++request;let base=location.href.split('#')[0];try{base=localStorage.getItem(`holiday-share:${topic}`)||base}catch{}
  const choices=config.targets(),current=config.current();config.modal(`<div id="activity-share" data-topic="${topic}"><h2>${esc(config.label())} · 학생 활동 QR</h2><p>학생 기기에서 먼저 접속을 확인하세요. 교사 화면과 학생 화면은 독립적으로 움직입니다.</p><div class="activity-qr-layout"><div id="activity-qr-result" class="qr-result"><p>주소를 확인하고 있어요.</p></div><div><label for="activity-qr-target">학생 활동</label><select id="activity-qr-target">${choices.map(t=>`<option value="${esc(t.id)}" ${String(t.id)===String(current)?'selected':''}>${esc(t.label)}</option>`).join('')}</select><label for="activity-share-base">공개 주소 또는 교실 네트워크 주소</label><input id="activity-share-base" type="url" value="${esc(base)}"><div id="activity-qr-networks"></div><button data-share-build="${topic}">QR 만들기</button><p id="activity-qr-status" role="status">localhost 주소로는 다른 학생 기기가 접속할 수 없습니다.</p><p>학생 이름·응답을 자동 수집하지 않습니다. QR이 열리지 않으면 말·그림·종이로 같은 활동에 참여하세요.</p></div></div></div>`);
  try{if(loopback(new URL(base).hostname)){const response=await fetch('/classroom-addresses',{cache:'no-store'});if(!response.ok)throw Error();const info=await response.json();if(token!==request||!document.getElementById('activity-share'))return;const addresses=(info.addresses||[]).filter(a=>{try{const u=new URL(a.url);return u.protocol==='http:'&&privateIp(u.hostname)}catch{return false}});if(addresses.length){document.getElementById('activity-share-base').value=addresses[0].url;document.getElementById('activity-qr-networks').innerHTML=`<label for="activity-qr-network">교실 네트워크 선택</label><select id="activity-qr-network"><option value="">직접 입력</option>${addresses.map((a,i)=>`<option value="${esc(a.url)}" ${i===0?'selected':''}>${esc(a.name)} · ${esc(a.url)}</option>`).join('')}</select>`;}}}catch{/* Hosted/file environments offer manual input rather than an unusable localhost QR. */}
  if(token===request&&document.getElementById('activity-share'))build(topic);
 }
 document.addEventListener('click',e=>{const topic=e.target.closest('button')?.dataset.shareBuild;if(topic)build(topic)});
 document.addEventListener('change',e=>{const topic=document.getElementById('activity-share')?.dataset.topic;if(!topic)return;if(e.target.id==='activity-qr-network'&&e.target.value){document.getElementById('activity-share-base').value=e.target.value;build(topic)}if(e.target.id==='activity-qr-target')build(topic)});
 return {register(topic,config){configs[topic]=config},open,targetUrl};
})();
